/**
 * Fuzz of `streams.ts#decodeStream` and `streams.ts#readObjectStream`, called directly. Lot 3 of the PDF fuzz design
 * (16/11/2026).
 * Input: bytes generated by fast-check, encoded by test encoders written from ISO 32000-1:2008 §7.4
 * (`stream-encoders.test.support.ts`) through a random chain of one to four filters, a PNG predictor on the last one now
 * and then; object streams (§7.5.7) whose members are generated values spelled by the lot 2 writer.
 * Properties: decode(encode(x)) = x; an object stream gives back its numbers and members; a damaged input (bytes cut,
 * overwritten or inserted, parameters out of range) gives a value or a refusal of ours, never a raw error, and the
 * output stays under the reader's ceiling (`MAX_DECODED_STREAM_BYTES`).
 *
 * The seed is fixed (`PDF_FUZZ_SEED`): a red run replays as is. The run counts are the written ones, times the weekly
 * multiplier (`lib/pdf-fuzz-runs.test.support.ts`).
 * NOT covered: reaching the ceilings (the inputs are small; `streams.test.ts` holds the bombs), the TIFF predictor
 * (refused by design), image filters (kept raw by design).
 */

import fc from "fast-check";
import { describe, expect, it, vi } from "vitest";

import { MAX_DECODED_STREAM_BYTES } from "./bounds";
import type { PdfStream, PdfValue } from "./objects";
import { PdfObjectsRefusal } from "./refusal";
import { chainDict, encodeChain, STREAM_FILTERS, takesParms, type FilterStep } from "./stream-encoders.test.support";
import { decodeStream, readObjectStream } from "./streams";
import {
  Choices,
  drawsArb,
  expectedValue,
  separator,
  valueArb,
  type ValueModel,
  writeValue,
} from "./pdf-syntax-writer.test.support";
import { PDF_FUZZ_SEED } from "../pdf-fuzz-outcome.test.support";
import { fuzzRuns, fuzzTestTimeout } from "../../lib/pdf-fuzz-runs.test.support";

vi.setConfig({ testTimeout: fuzzTestTimeout(30000, process.env) });

const params = (baseRuns: number): fc.Parameters<unknown> => ({
  numRuns: fuzzRuns(baseRuns, process.env),
  seed: PDF_FUZZ_SEED,
  timeout: 8000,
});

const latin1 = (text: string): Uint8Array => Uint8Array.from(text, (char) => char.charCodeAt(0));

function concat(parts: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let at = 0;
  for (const part of parts) {
    out.set(part, at);
    at += part.length;
  }
  return out;
}

/** Pseudo-random bytes from a seed (a linear congruential generator): long data without kilobytes in a counter-example. */
function longData(length: number, seed: number, alphabet: number): Uint8Array {
  const out = new Uint8Array(length);
  let state = seed >>> 0;
  for (let i = 0; i < length; i += 1) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    out[i] = (state >>> 24) % alphabet;
  }
  return out;
}

/** Short random bytes; bytes from a small alphabet (runs, long LZW strings); and long data that drives LZW past nine,
 *  ten and eleven bits and fills its table (4 096 entries). */
const dataArb: fc.Arbitrary<Uint8Array> = fc.oneof(
  { weight: 4, arbitrary: fc.uint8Array({ maxLength: 256 }) },
  {
    weight: 3,
    arbitrary: fc.array(fc.integer({ min: 0, max: 3 }), { maxLength: 1500 }).map((a) => Uint8Array.from(a)),
  },
  {
    weight: 1,
    arbitrary: fc
      .record({ length: fc.integer({ min: 2000, max: 12000 }), seed: fc.nat(), alphabet: fc.constantFrom(4, 64, 256) })
      .map(({ length, seed, alphabet }) => longData(length, seed, alphabet)),
  },
);

const stepArb = (last: boolean): fc.Arbitrary<FilterStep> =>
  fc
    .record({
      filter: fc.constantFrom(...STREAM_FILTERS),
      predictor: fc.option(
        fc.record({
          predictor: fc.integer({ min: 10, max: 15 }),
          columns: fc.integer({ min: 1, max: 8 }),
          colors: fc.integer({ min: 1, max: 4 }),
        }),
        { nil: undefined },
      ),
      earlyChange: fc.option(fc.constantFrom<0 | 1>(0, 1), { nil: undefined }),
    })
    .map(({ filter, predictor, earlyChange }) => ({
      filter,
      // A predictor shapes the filter's OUTPUT into rows: only the last filter's output is the data itself, which the
      // case trims to whole rows.
      ...(predictor !== undefined && last && takesParms(filter) ? { predictor } : {}),
      ...(earlyChange !== undefined && filter === "LZWDecode" ? { earlyChange } : {}),
    }));

const stepsArb: fc.Arbitrary<FilterStep[]> = fc
  .tuple(fc.array(stepArb(false), { maxLength: 3 }), stepArb(true))
  .map(([head, last]) => [...head, last]);

/** The data trimmed to whole rows of the last step's predictor. */
function shaped(data: Uint8Array, steps: readonly FilterStep[]): Uint8Array {
  const predictor = steps[steps.length - 1]?.predictor;
  if (predictor === undefined) return data;
  const stride = predictor.columns * predictor.colors;
  return data.subarray(0, data.length - (data.length % stride));
}

interface Encoded {
  readonly bytes: Uint8Array;
  readonly stream: PdfStream;
  readonly data: Uint8Array;
}

/** The data encoded, set between arbitrary bytes: the stream's `start` and `length` must be honoured. */
function encoded(
  data: Uint8Array,
  steps: readonly FilterStep[],
  prefix: Uint8Array,
  suffix: Uint8Array,
  choices: Choices,
): Encoded {
  const plain = shaped(data, steps);
  const body = encodeChain(plain, steps, choices);
  const dict = chainDict(steps, choices);
  return {
    bytes: concat([prefix, body, suffix]),
    stream: { kind: "stream", dict, start: prefix.length, length: body.length },
    data: plain,
  };
}

const caseArb = fc.record({
  data: dataArb,
  steps: stepsArb,
  prefix: fc.uint8Array({ maxLength: 8 }),
  suffix: fc.uint8Array({ maxLength: 8 }),
  draws: drawsArb,
});

/** Bytes that mean something to one filter or another: ends of data (`>`, `~>`, 128), a `z`, digits at the edges of
 *  base 85, a clear code's high bits, a zlib header. */
const FRAGMENTS: readonly Uint8Array[] = [
  ">",
  "~>",
  "~",
  "z",
  "!",
  "u",
  "v",
  "\x80",
  "\xff",
  "\x00",
  "x\x9c",
  "0",
  "g",
].map(latin1);

interface Damage {
  readonly cut: number;
  readonly writes: readonly { readonly at: number; readonly byte: number }[];
  readonly insert: { readonly at: number; readonly fragment: number } | null;
}

const damageArb: fc.Arbitrary<Damage> = fc.record({
  cut: fc.nat(),
  writes: fc.array(fc.record({ at: fc.nat(), byte: fc.integer({ min: 0, max: 255 }) }), { maxLength: 4 }),
  insert: fc.option(fc.record({ at: fc.nat(), fragment: fc.nat({ max: FRAGMENTS.length - 1 }) }), { nil: null }),
});

/** The body cut short (or whole, now and then), up to four bytes overwritten, maybe one fragment inserted. */
function damagedBody(body: Uint8Array, damage: Damage): Uint8Array {
  let out: Uint8Array = body.slice(0, damage.cut % 5 === 0 ? body.length : damage.cut % (body.length + 1));
  if (damage.insert !== null) {
    const at = damage.insert.at % (out.length + 1);
    out = concat([out.subarray(0, at), FRAGMENTS[damage.insert.fragment] as Uint8Array, out.subarray(at)]);
  }
  for (const { at, byte } of damage.writes) if (out.length > 0) out[at % out.length] = byte;
  return out;
}

/** A decode that gives a value or a refusal of ours, never a raw error; the value under the ceiling. */
function settle(read: () => Uint8Array): "read" | "refused" {
  try {
    const out = read();
    expect(out.length, "decoded bytes under the ceiling").toBeLessThanOrEqual(MAX_DECODED_STREAM_BYTES);
    return "read";
  } catch (error) {
    expect(error, "a refusal of ours, never a raw error").toBeInstanceOf(PdfObjectsRefusal);
    return "refused";
  }
}

describe("decodeStream - chains of filters encoded after ISO 32000-1 §7.4", () => {
  it("decodes what the encoders wrote: decode(encode(x)) = x (7.4.2-7.4.5)", () => {
    fc.assert(
      fc.property(caseArb, ({ data, steps, prefix, suffix, draws }) => {
        const { bytes, stream, data: plain } = encoded(data, steps, prefix, suffix, new Choices(draws));
        // `inflateSync` gives a Buffer: compared as plain bytes.
        expect(Uint8Array.from(decodeStream(bytes, stream))).toEqual(Uint8Array.from(plain));
      }),
      params(150),
    );
  });

  it("decodes LZW across every code width, a full table and clear codes included (7.4.4.2, Table 8 EarlyChange)", () => {
    const longArb = fc.record({
      length: fc.integer({ min: 3000, max: 20000 }),
      seed: fc.nat(),
      alphabet: fc.constantFrom(2, 16, 256),
      earlyChange: fc.constantFrom<0 | 1 | undefined>(0, 1, undefined),
      draws: drawsArb,
    });
    fc.assert(
      fc.property(longArb, ({ length, seed, alphabet, earlyChange, draws }) => {
        const data = longData(length, seed, alphabet);
        const steps: FilterStep[] = [{ filter: "LZWDecode", ...(earlyChange === undefined ? {} : { earlyChange }) }];
        const { bytes, stream } = encoded(data, steps, new Uint8Array(0), new Uint8Array(0), new Choices(draws));
        expect(Uint8Array.from(decodeStream(bytes, stream))).toEqual(data);
      }),
      params(20),
    );
  });

  it("damaged bytes give a value or a refusal of ours, never a raw error, and stay under the ceiling", () => {
    const seen = { read: 0, refused: 0 };
    fc.assert(
      fc.property(caseArb, damageArb, ({ data, steps, draws }, damage) => {
        const { bytes, stream } = encoded(data, steps, new Uint8Array(0), new Uint8Array(0), new Choices(draws));
        const body = damagedBody(bytes, damage);
        seen[settle(() => decodeStream(body, { ...stream, start: 0, length: body.length }))] += 1;
      }),
      params(300),
    );
    // Both branches must be exercised, or the property sees only one side. Measured on 24/11/2026 with this seed:
    // 20 of 300 damaged streams still decode.
    expect(seen.read, "damaged streams that still decode").toBeGreaterThan(0);
    expect(seen.refused, "damaged streams refused").toBeGreaterThan(0);
  });

  it("parameters out of range give a value or a refusal of ours, never a raw error (Table 8)", () => {
    const seen = { read: 0, refused: 0 };
    const wild = fc.oneof(
      fc.integer({ min: -3, max: 20 }),
      fc.constantFrom(0x7fffffff, 2 ** 40, -(2 ** 40), 1.5, Number.MAX_SAFE_INTEGER),
    );
    const parmsArb = fc.dictionary(
      fc.constantFrom("Predictor", "Columns", "Colors", "BitsPerComponent", "EarlyChange"),
      wild,
    );
    fc.assert(
      fc.property(caseArb, parmsArb, ({ data, steps, draws }, wildParms) => {
        const { bytes, stream } = encoded(data, steps, new Uint8Array(0), new Uint8Array(0), new Choices(draws));
        const entries = new Map<string, PdfValue>(
          Object.entries(wildParms).map(([key, value]) => [key, { kind: "number", value }]),
        );
        const parms: PdfValue = { kind: "dict", entries };
        const dict = new Map(stream.dict);
        dict.set("DecodeParms", steps.length === 1 ? parms : { kind: "array", items: steps.map(() => parms) });
        seen[settle(() => decodeStream(bytes, { ...stream, dict }))] += 1;
      }),
      params(200),
    );
    // Measured on 24/11/2026 with this seed: 109 of 200 still decode.
    expect(seen.read, "streams that still decode").toBeGreaterThan(0);
    expect(seen.refused, "streams refused").toBeGreaterThan(0);
  });
});

// ---------------------------------------------------------------------------------------------------------------------
// Object streams (§7.5.7).

interface ObjectStreamCase {
  readonly numbers: readonly number[];
  readonly members: readonly ValueModel[];
}

/** Distinct object numbers, each with a value; §7.5.7 forbids a stream inside, which the generator cannot make. */
const objectStreamArb: fc.Arbitrary<ObjectStreamCase> = fc
  .uniqueArray(fc.integer({ min: 1, max: 100000 }), { minLength: 1, maxLength: 12 })
  .chain((numbers) =>
    fc.array(valueArb(true), { minLength: numbers.length, maxLength: numbers.length }).map((members) => ({
      numbers,
      members,
    })),
  );

/** §7.5.7: `N` pairs of `number offset`, the members from `First`, each offset relative to `First`; white space or
 *  comments between all of them. Returns the decoded data and `First`. */
function objectStreamData(model: ObjectStreamCase, choices: Choices): { data: Uint8Array; first: number } {
  const members: Uint8Array[] = [];
  const offsets: number[] = [];
  let at = 0;
  for (const member of model.members) {
    offsets.push(at);
    const written = concat([writeValue(member, choices), latin1(separator(choices))]);
    members.push(written);
    at += written.length;
  }
  const pairs = model.numbers.map((num, i) => `${num} ${offsets[i]}`).join(" ");
  const head = latin1(`${pairs}${separator(choices)}`);
  return { data: concat([head, ...members]), first: head.length };
}

function objectStream(model: ObjectStreamCase, steps: readonly FilterStep[], choices: Choices) {
  const { data, first } = objectStreamData(model, choices);
  const plainSteps = steps.map(({ filter, earlyChange }) => ({
    filter,
    ...(earlyChange === undefined ? {} : { earlyChange }),
  }));
  const body = encodeChain(data, plainSteps, choices);
  const dict = chainDict(plainSteps, choices);
  dict.set("Type", { kind: "name", value: "ObjStm" });
  dict.set("N", { kind: "number", value: model.numbers.length });
  dict.set("First", { kind: "number", value: first });
  const stream: PdfStream = { kind: "stream", dict, start: 0, length: body.length };
  return { bytes: body, stream, data, first };
}

const objectStreamCaseArb = fc.record({ model: objectStreamArb, steps: stepsArb, draws: drawsArb });

describe("readObjectStream - generated object streams (7.5.7)", () => {
  it("gives back the numbers and each member written", () => {
    fc.assert(
      fc.property(objectStreamCaseArb, ({ model, steps, draws }) => {
        const { bytes, stream } = objectStream(model, steps, new Choices(draws));
        const members = readObjectStream(bytes, stream, decodeStream);
        expect(members.numbers).toEqual(model.numbers);
        model.numbers.forEach((num, i) => {
          expect(members.valueOf(num)?.value, `member ${num}`).toEqual(expectedValue(model.members[i] as ValueModel));
        });
      }),
      params(150),
    );
  });

  it("damaged data or counts give members or a refusal of ours, never a raw error", () => {
    const seen = { read: 0, refused: 0 };
    const countsArb = fc.record({
      n: fc.option(fc.integer({ min: -2, max: 40 })),
      first: fc.option(fc.integer({ min: -2, max: 400 })),
    });
    fc.assert(
      fc.property(objectStreamCaseArb, damageArb, countsArb, ({ model, steps, draws }, damage, counts) => {
        const { stream, data } = objectStream(model, steps, new Choices(draws));
        const damaged = damagedBody(data, damage);
        const dict = new Map(stream.dict);
        dict.delete("Filter");
        dict.delete("DecodeParms");
        if (counts.n !== null) dict.set("N", { kind: "number", value: counts.n });
        if (counts.first !== null) dict.set("First", { kind: "number", value: counts.first });
        try {
          const members = readObjectStream(
            damaged,
            { kind: "stream", dict, start: 0, length: damaged.length },
            decodeStream,
          );
          for (const num of members.numbers) members.valueOf(num);
          seen.read += 1;
        } catch (error) {
          expect(error, "a refusal of ours, never a raw error").toBeInstanceOf(PdfObjectsRefusal);
          seen.refused += 1;
        }
      }),
      params(300),
    );
    // Measured on 24/11/2026 with this seed: 12 of 300 still read.
    expect(seen.read, "damaged object streams that still read").toBeGreaterThan(0);
    expect(seen.refused, "damaged object streams refused").toBeGreaterThan(0);
  });
});
